4-# the results.
5-#
6-# A test never reads a setting itself. It declares a parameter bound to it,
7:#   [MaesterParameter(Setting = 'ParkedDomains')] [string[]] $ParkedDomains = @()
8-# and the engine binds the GlobalSettings value when the test's TestSettings row does not set one. The
9-# parameter's type must match Type here, and it takes Kind from here when it declares none. A setting holds
10-# a fact about the tenant or a choice the organisation makes once (parked domains, break-glass accounts),
11-# never a value a benchmark sets, which stays a parameter of that test. Name a setting after what it holds,
12-# never after a test or a suite.
13-@{
14-    SchemaVersion = '1.0'
15-    Settings      = @{
16-        EmergencyAccessAccounts           = @{ Type = 'object[]'; Default = @(); Sensitive = $false; Description = 'Emergency access (break glass) accounts and groups excluded from Conditional Access checks.' }
17:        ParkedDomains                     = @{ Type = 'string[]'; Kind = 'Entra.Domain'; Default = @(); Sensitive = $false; Description = 'Accepted domains that never send email. The email authentication checks expect them to deny all mail.' }
18-        DefenderEndpointPolicyFiltering   = @{ Type = 'string'; Default = 'OnlyAssigned'; Sensitive = $false; Description = 'Which Defender for Endpoint policies the Defender checks read: All, IncludeUnassigned or OnlyAssigned.' }
19-        DefenderEndpointComplianceLogic   = @{ Type = 'string'; Default = 'EffectivePolicy'; Sensitive = $false; Description = 'How the Defender for Endpoint checks combine policies: EffectivePolicy, AllPolicies or AnyPolicy.' }
20-        DataverseEnvironmentUrl           = @{ Type = 'string'; Default = ''; Sensitive = $false; Description = 'URL of the Dataverse environment that the Copilot Studio checks read.' }
21-        AzureDevOpsOrganization           = @{ Type = 'string'; Default = ''; Sensitive = $false; Description = 'Azure DevOps organization that Connect-Maester -Service AzureDevOps connects to.' }
22-        GitHubOrganization                = @{ Type = 'string'; Default = ''; Sensitive = $false; Description = 'GitHub organization that the GitHub checks read.' }
23-        GitHubApiBaseUri                  = @{ Type = 'string'; Default = 'https://api.github.com'; Sensitive = $false; Description = 'Base URI of the GitHub REST API.' }
24-        GitHubApiVersion                  = @{ Type = 'string'; Default = '2022-11-28'; Sensitive = $false; Description = 'GitHub REST API version.' }
25-    }
26-}
