     1	﻿BeforeAll {
     2	    . "$PSScriptRoot/../helpers/Use-MtModuleFunction.ps1"
     3	    # Check functions that became native tests are not exported.
     4	    Use-MtModuleFunction -Name Test-MtCisaDkim, Test-MtCisDkim
     5	    Import-Module "$PSScriptRoot/../../Maester.psd1" -Force
     6	}
     7	
     8	Describe 'DKIM checks with no signing configuration' -ForEach @(
     9	    @{ CommandName = 'Test-MtCisDkim' }
    10	    @{ CommandName = 'Test-MtCisaDkim' }
    11	) {
    12	    BeforeEach {
    13	        Mock -ModuleName Maester Test-MtConnection { return $true }
    14	        Mock -ModuleName Maester Add-MtTestResultDetail { }
    15	        Mock -ModuleName Maester Get-MailAuthenticationRecord {
    16	            throw 'DNS lookup should not be attempted without a DKIM signing configuration'
    17	        }
    18	    }
    19	
    20	    It '<CommandName> handles domain <DomainName> correctly' -ForEach @(
    21	        @{
    22	            DomainName                = 'contoso.onmicrosoft.com'
    23	            InitialDomain             = $true
    24	            IsCoexistenceDomain       = $false
    25	            SendingFromDomainDisabled = $false
    26	            # Test-MtCisDkim (CIS v7.0.0) excludes the initial (MOERA) domain from the audit entirely,
    27	            # while Test-MtCisaDkim still auto-passes it.
    28	            ExpectedResultByCommand   = @{
    29	                'Test-MtCisDkim'  = $null
    30	                'Test-MtCisaDkim' = $true
    31	            }
    32	        }
    33	        @{
    34	            DomainName                = 'secondary.onmicrosoft.com'
    35	            InitialDomain             = $false
    36	            IsCoexistenceDomain       = $false
    37	            SendingFromDomainDisabled = $false
    38	            ExpectedResultByCommand   = @{
    39	                'Test-MtCisDkim'  = $false
    40	                'Test-MtCisaDkim' = $false
    41	            }
    42	        }
    43	        @{
    44	            DomainName                = 'parked.example'
    45	            InitialDomain             = $false
    46	            IsCoexistenceDomain       = $false
    47	            SendingFromDomainDisabled = $true
    48	            ExpectedResultByCommand   = @{
    49	                'Test-MtCisDkim'  = $null
    50	                'Test-MtCisaDkim' = $null
    51	            }
    52	        }
    53	        @{
    54	            DomainName                = 'contoso.mail.onmicrosoft.com'
    55	            InitialDomain             = $false
    56	            IsCoexistenceDomain       = $true
    57	            SendingFromDomainDisabled = $false
    58	            # Both commands exclude coexistence domains from the audit entirely.
    59	            ExpectedResultByCommand   = @{
    60	                'Test-MtCisDkim'  = $null
    61	                'Test-MtCisaDkim' = $null
    62	            }
    63	        }
    64	        @{
    65	            DomainName                = 'contoso.mail.onmicrosoft.com'
    66	            InitialDomain             = $false
    67	            IsCoexistenceDomain       = $true
    68	            SendingFromDomainDisabled = $true
    69	            ExpectedResultByCommand   = @{
    70	                'Test-MtCisDkim'  = $null
    71	                'Test-MtCisaDkim' = $null
    72	            }
    73	        }
    74	        @{
    75	            DomainName                = 'contoso.com'
    76	            InitialDomain             = $false
    77	            IsCoexistenceDomain       = $false
    78	            SendingFromDomainDisabled = $false
    79	            ExpectedResultByCommand   = @{
    80	                'Test-MtCisDkim'  = $false
    81	                'Test-MtCisaDkim' = $false
    82	            }
    83	        }
    84	    ) {
    85	        Mock -ModuleName Maester Get-MtExo {
    86	            if ($Request -eq 'AcceptedDomain') {
    87	                return [PSCustomObject]@{
    88	                    DomainName                = $DomainName
    89	                    InitialDomain             = $InitialDomain
    90	                    IsCoexistenceDomain       = $IsCoexistenceDomain
    91	                    SendingFromDomainDisabled = $SendingFromDomainDisabled
    92	                }
    93	            }
    94	
    95	            return @()
    96	        }
    97	
    98	        $expectedResult = $ExpectedResultByCommand[$CommandName]
    99	
   100	        $result = & $CommandName
   101	        if ($null -eq $expectedResult) {
   102	            $result | Should -BeNullOrEmpty
   103	        } else {
   104	            $result | Should -Be $expectedResult
   105	        }
   106	        Should -Invoke Get-MailAuthenticationRecord -ModuleName Maester -Exactly 0
   107	    }
   108	}
   109	
   110	Describe 'DKIM checks for coexistence domains with a signing configuration' -ForEach @(
   111	    @{ CommandName = 'Test-MtCisDkim' }
   112	    @{ CommandName = 'Test-MtCisaDkim' }
   113	) {
