        if ($domain.IsCoexistenceDomain -eq $true) {
            $dkimRecord = [PSCustomObject]@{
                domain     = $domain.DomainName
                pass       = 'Skipped'
                reason     = 'coexistence domain'
                dkimRecord = $null
            }
            $dkimRecords += $dkimRecord
            continue
        }

        $dkimSigningConfig = $dkimSigningConfigs | Where-Object {`
                $_.domain -eq $domain.domainname
        }

        if (-not $dkimSigningConfig) {
            $dkimRecord = [PSCustomObject]@{
                domain     = $domain.DomainName
                pass       = if ($domain.InitialDomain -eq $true) { 'Passed' } else { 'Failed' }
                reason     = if ($domain.InitialDomain -eq $true) { 'Microsoft auto-signs DKIM for the initial onmicrosoft.com domain' } else { 'No DkimSigningConfig found for domain' }
                dkimRecord = $null
            }
            $dkimRecords += $dkimRecord
            continue
        }
        if ((Get-Date) -gt $dkimSigningConfig.RotateOnDate) {
            if ($Selector -ne $dkimSigningConfig.SelectorAfterRotateOnDate) {
                Write-Verbose "Using DKIM $($dkimSigningConfig.SelectorAfterRotateOnDate) based on EXO config"
            }
            $Selector = $dkimSigningConfig.SelectorAfterRotateOnDate
        } else {
            if ($Selector -ne $dkimSigningConfig.SelectorBeforeRotateOnDate) {
                Write-Verbose "Using DKIM $($dkimSigningConfig.SelectorBeforeRotateOnDate) based on EXO config"
            }
            $selector = $dkimSigningConfig.SelectorBeforeRotateOnDate
        }

        $isMicrosoftDomain = $domain.DomainName.EndsWith(".onmicrosoft.com")
        $isMicrosoftExoHybridDomain = $domain.DomainName.EndsWith(".mail.onmicrosoft.com")
        $dkimDnsName = if ($isMicrosoftExoHybridDomain) {
            "$($Selector)._domainkey.$($domain.DomainName)"
        } elseif ($isMicrosoftDomain) {
            $dkimSigningConfig."$($selector)CNAME"
        } else {
            "$($Selector)._domainkey.$($domain.DomainName)"
        }
        $dkimRecord = Get-MailAuthenticationRecord -DomainName $domain.DomainName -DkimDnsName $dkimDnsName -Records DKIM
        $dkimRecord | Add-Member -MemberType NoteProperty -Name "pass" -Value "Failed"
        $dkimRecord | Add-Member -MemberType NoteProperty -Name "reason" -Value ""

        if (-not $dkimSigningConfig.enabled) {
            $dkimRecord.pass = 'Failed'
            $dkimRecord.reason = 'DKIM is disabled'
        } elseif ($dkimRecord.dkimRecord.GetType().Name -eq 'DKIMRecord') {
            if (-not $dkimRecord.dkimRecord.validBase64) {
                $dkimRecord.reason = 'Malformed public key'
            } else {
                $dkimRecord.pass = 'Passed'
            }
        } elseif ($domain.DomainName -like '*.onmicrosoft.com') {
            $dkimRecord.reason = "Recommendation: Disable sending from domain"
        } elseif ($dkimRecord.dkimRecord -like "*not available") {
            $dkimRecord.pass = "Skipped"
            $dkimRecord.reason = $dkimRecord.dkimRecord
        } else {
            $dkimRecord.reason = $dkimRecord.dkimRecord
        }

        $dkimRecords += $dkimRecord
    }

if ("Failed" -in $dkimRecords.pass) {
        $testResult = $false
    } elseif ("Failed" -notin $dkimRecords.pass -and "Passed" -notin $dkimRecords.pass) {
        Add-MtTestResultDetail -SkippedBecause NotSupported
        return $null
    } else {
        $testResult = $true
    }

    $portalLink = "https://security.microsoft.com/authentication?viewid=DKIM"

    if ($testResult) {
        $testResultMarkdown = "Well done. Your tenant's domains have DKIM configured and valid records exist.`n`n%TestResult%"
    } else {
        $testResultMarkdown = "Your tenant's domains do not have DKIM fully deployed. Review [EXO configuration]($portalLink) and DNS records.`n`n%TestResult%"
    }

    $passResult = "✅ Pass"
    $failResult = "❌ Fail"
    $skipResult = "🗄️ Skip"
    $result = "| Domain | Result | Reason |`n"
    $result += "| --- | --- | --- |`n"
    foreach ($item in $dkimRecords | Sort-Object -Property domain) {
        switch ($item.pass) {
            "Passed" { $itemResult = $passResult }
            "Skipped" { $itemResult = $skipResult }
            "Failed" { $itemResult = $failResult }
        }
        $result += "| $($item.domain) | $($itemResult) | $($item.reason) |`n"
    }

    $testResultMarkdown = $testResultMarkdown -replace "%TestResult%", $result

    Add-MtTestResultDetail -Result $testResultMarkdown

    return $testResult
}

﻿function Test-MtCisaDmarcRecordReject {
    <#
    .SYNOPSIS
    Checks state of DMARC records for all exo domains

    .DESCRIPTION
    The DMARC message rejection option SHALL be p=reject.

    .EXAMPLE
    Test-MtCisaDmarcRecordReject

    Returns true if DMARC record with reject policy exists for every domain

    .LINK
    https://maester.dev/docs/commands/Test-MtCisaDmarcRecordReject
    #>
    [MaesterTest(
        Id = 'CISA.MS.EXO.4.2',
        Title = 'The DMARC message rejection option SHALL be p=reject.',
        Product = 'exchange',
        Feature = 'email-authentication',
        Area = 'email-protection',
        ResourceType = 'Domain',
        Severity = 'High',
        UserImpact = 'Medium',
        ImplementationCost = 'High',
        Mitre = ('T1566', 'T1598', 'T1684.002'),
        Control = 'cisa-scuba:MS.EXO.4.2',
        Service = 'ExchangeOnline',
        Author = 'soulemike',
        Contributor = 'JeanPhilippeGeorge'
    )]
    [CmdletBinding()]
    [OutputType([bool])]
    param(
        # Check 2nd Level Domains Explicitly per CISA
        [switch]$Strict
    )

    $acceptedDomains = Get-MtExo -Request AcceptedDomain
    <# Parked domains should have DMARC with reject policy
    $sendingDomains = $acceptedDomains | Where-Object {`
        -not $_.SendingFromDomainDisabled
    }
    #>
    $expandedDomains = @()
    foreach($domain in $acceptedDomains){
        # If it's the coexistence domain (contoso.mail.onmicrosoft.com), skip the 2nd level check.
        # If it's the initial domain (contoso.onmicrosoft.com), skip the 2nd level check. We cannot manage onmicrosoft.com.
        if ($domain.IsCoexistenceDomain -or $domain.InitialDomain) {
            $expandedDomains += [PSCustomObject]@{
                DomainName = $domain.DomainName
                IsCoexistenceDomain = $domain.IsCoexistenceDomain
            }
            continue
        }

        #This regex does NOT capture for third level domain scenarios
        #e.g., example.co.uk; example.ny.us;
        $matchDomain = "(?:^|\.)(?'second'[\w-]+\.[\w-]+$)"
        $dmarcMatch = $domain.domainname -match $matchDomain
        if($dmarcMatch){
            $expandedDomains += [PSCustomObject]@{
                DomainName = $Matches.second
                IsCoexistenceDomain = $domain.IsCoexistenceDomain
            }
            if($domain.domainname -ne $Matches.second){
                $expandedDomains += [PSCustomObject]@{
                    DomainName = $domain.domainname
                    IsCoexistenceDomain = $domain.IsCoexistenceDomain
                }
            }
        }else{
            $expandedDomains += [PSCustomObject]@{
                DomainName = $domain.domainname
                IsCoexistenceDomain = $domain.IsCoexistenceDomain
            }
        }
    }

    # Sort and remove duplicate Domains
    $expandedDomains = $expandedDomains |  Sort-Object DomainName, IsCoexistenceDomain -Unique

    $dmarcRecords = @()
    foreach($domain in ($expandedDomains | Sort-Object -Unique)){
        $dmarcRecord = Get-MailAuthenticationRecord -DomainName $domain.DomainName -Records DMARC
        $dmarcRecord | Add-Member -MemberType NoteProperty -Name "pass" -Value "Failed"
        $dmarcRecord | Add-Member -MemberType NoteProperty -Name "reason" -Value ""

        $checkType = $dmarcRecord.dmarcRecord.GetType().Name -eq "DMARCRecord"

        if($domain.IsCoexistenceDomain){
            $dmarcRecord.pass = "Skipped"
            $dmarcRecord.reason = "Not applicable for coexistence domain"
        }elseif($checkType -and $dmarcRecord.dmarcRecord.policy -eq "reject"){
            $dmarcRecord.pass = "Passed"
        }elseif($checkType -and $dmarcRecord.dmarcRecord.policy -ne "reject"){
            $dmarcRecord.reason = "Policy is not reject"
        }elseif($checkType -and $dmarcRecord.dmarcRecord.policySubdomain -in @("none","quarantine")){
            $dmarcRecord.reason = "Subdomain policy is not reject"
        }elseif($dmarcRecord.dmarcRecord -like "*not available"){
            $dmarcRecord.pass = "Skipped"
            $dmarcRecord.reason = $dmarcRecord.dmarcRecord
        }elseif($domain -eq 'onmicrosoft.com' -or $domain -like '*.mail.onmicrosoft.com'){
            $dmarcRecord.pass = "Skipped"
            $dmarcRecord.reason = 'Not applicable'
        }else{
            $dmarcRecord.reason = $dmarcRecord.dmarcRecord
        }

        $dmarcRecords += $dmarcRecord
    }

    if("Failed" -in $dmarcRecords.pass -and $Strict){
        $testResult = $false
    }elseif("Failed" -in $dmarcRecords.pass -and -not $Strict){
        if("Failed" -in ($dmarcRecords|Where-Object{$_.domain -in $acceptedDomains.DomainName}).pass){
            $testResult = $false
        }else{
            $testResult = $true
        }
    }elseif("Failed" -notin $dmarcRecords.pass -and "Passed" -notin $dmarcRecords.pass){
        Add-MtTestResultDetail -SkippedBecause NotSupported
        return $null
    }else{
        $testResult = $true
    }

    if($testResult){
        $testResultMarkdown = "Well done. Your tenant's domains have a DMARC record with reject policy. Review report targets.`n`n%TestResult%"
    }else{
        $testResultMarkdown = "Your tenant's domains do not have a DMARC record with reject policy.`n`n%TestResult%"
    }

    $passResult = "✅ Pass"
    $failResult = "❌ Fail"
    $skipResult = "🗄️ Skip"
    $result = "| Domain | Result | Reason | Policy | Subdomain Policy |`n"
    $result += "| --- | --- | --- | --- | --- |`n"
    foreach ($item in $dmarcRecords) {
        switch($item.pass){
            "Passed" {$itemResult = $passResult}
            "Skipped" {$itemResult = $skipResult}
            "Failed" {$itemResult = $failResult}
        }

        $result += "| $($item.domain) | $($itemResult) | $($item.reason) | $($item.dmarcRecord.policy) | $($item.dmarcRecord.policySubdomain) |`n"
    }

    $testResultMarkdown = $testResultMarkdown -replace "%TestResult%", $result

    Add-MtTestResultDetail -Result $testResultMarkdown

    return $testResult
}

﻿function Test-MtCisaDmarcAggregateCisa {
    <#
    .SYNOPSIS
    Checks state of DMARC records for all exo domains

    .DESCRIPTION
    The DMARC point of contact for aggregate reports SHALL include reports@dmarc.cyber.dhs.gov.

    .EXAMPLE
    Test-MtCisaDmarcAggregateCisa

    Returns true if DMARC record with reject policy exists for every domain if a .gov domain exists

    .EXAMPLE
    Test-MtCisaDmarcAggregateCisa -Force

    Returns true if DMARC record with reject policy exists for every domain

    .LINK
    https://maester.dev/docs/commands/Test-MtCisaDmarcAggregateCisa
    #>
    [MaesterTest(
        Id = 'CISA.MS.EXO.4.3',
        Title = 'The DMARC point of contact for aggregate reports SHALL include reports@dmarc.cyber.dhs.gov.',
        Product = 'exchange',
        Feature = 'email-authentication',
        Area = 'email-protection',
        ResourceType = 'Domain',
        Severity = 'Medium',
        UserImpact = 'Low',
        ImplementationCost = 'Low',
        Mitre = 'T1684.002',
        Control = 'cisa-scuba:MS.EXO.4.3',
        Service = 'ExchangeOnline',
        Author = 'soulemike'
    )]
    [CmdletBinding()]
    [OutputType([bool])]
    param(
        # Check all domains, not only .gov domains.
        [switch]$AllDomains,

        # Check 2nd Level Domains Explicitly per CISA
        [switch]$Strict
    )

    $acceptedDomains = Get-MtExo -Request AcceptedDomain
    <# Parked domains should have DMARC with reject policy
    $sendingDomains = $acceptedDomains | Where-Object {`
        -not $_.SendingFromDomainDisabled
    }
    #>
    $tldMatch = "^.*\.(?'tld'.*)$"
    $govDomains = $acceptedDomains | Where-Object {`
        $_ -imatch $tldMatch|Out-Null;
        if($Matches.tld -eq "gov"){$_}
    }

    if(!($govDomains) -and !($AllDomains)){
        Add-MtTestResultDetail -SkippedBecause NotDotGovDomain
        return $null
    }

    $expandedDomains = @()
    foreach($domain in $acceptedDomains){
        #This regex does NOT capture for third level domain scenarios
        #e.g., example.co.uk; example.ny.us;
        $matchDomain = "(?:^|\.)(?'second'[\w-]+\.[\w-]+$)"
        $dmarcMatch = $domain.domainname -match $matchDomain
        if($dmarcMatch){
            $expandedDomains += $Matches.second
            if($domain.domainname -ne $Matches.second){
                $expandedDomains += $domain.domainname
            }
        }else{
            $expandedDomains += $domain.domainname
        }
    }

    $dmarcRecords = @()
    foreach($domain in $expandedDomains){
        $dmarcRecord = Get-MailAuthenticationRecord -DomainName $domain -Records DMARC
        $dmarcRecord | Add-Member -MemberType NoteProperty -Name "pass" -Value "Failed"
        $dmarcRecord | Add-Member -MemberType NoteProperty -Name "reason" -Value ""

        $checkType = $dmarcRecord.dmarcRecord.GetType().Name -eq "DMARCRecord"
        $checkTarget = "reports@dmarc.cyber.dhs.gov" -in ($dmarcRecords.dmarcRecord.reportAggregate.mailAddress)

        if($checkType -and $checkTarget){
            $dmarcRecord.pass = "Passed"
        }elseif($checkType -and -not $checkTarget){
            $dmarcRecord.reason = "Missing CISA report target"
        }elseif($dmarcRecord.dmarcRecord -like "*not available"){
            $dmarcRecord.pass = "Skipped"
            $dmarcRecord.reason = $dmarcRecord.dmarcRecord
        }else{
            $dmarcRecord.reason = $dmarcRecord.dmarcRecord
        }

        $dmarcRecords += $dmarcRecord
    }

    if("Failed" -in $dmarcRecords.pass -and $Strict){
        $testResult = $false
    }elseif("Failed" -in $dmarcRecords.pass -and -not $Strict){
        if("Failed" -in ($dmarcRecords|Where-Object{$_.domain -in $acceptedDomains.DomainName}).pass){
            $testResult = $false
        }else{
            $testResult = $true
        }
    }elseif("Failed" -notin $dmarcRecords.pass -and "Passed" -notin $dmarcRecords.pass){
        Add-MtTestResultDetail -SkippedBecause NotSupported
        return $null
    }else{
        $testResult = $true
    }

    if($testResult){
        $testResultMarkdown = "Well done. Your tenant's domains have DMARC aggregate reports sent to CISA.`n`n%TestResult%"
    }else{
        $testResultMarkdown = "Your tenant's domains do not have DMARC aggregate reports sent to CISA.`n`n%TestResult%"
    }

    $passResult = "✅ Pass"
    $failResult = "❌ Fail"
    $result = "| Domain | Result | Reason | Targets |`n"
    $result += "| --- | --- | --- | --- |`n"
    foreach ($item in $dmarcRecords) {
        switch($item.pass){
            "Passed" {$itemResult = $passResult}
            "Failed" {$itemResult = $failResult}
        }
        $aggregates = $item.dmarcRecord.reportForensic.mailAddress
        $aggregatesCount = ($aggregates|Measure-Object).Count
        if($aggregatesCount -ge 3){
            $aggregates = "$($aggregates[0]), $($aggregates[1]), "
            $aggregates += "& ...$aggregatesCount targets"
        }elseif($aggregatesCount -gt 1){
            $aggregates = $aggregates -join ", "
        }

        $result += "| $($item.domain) | $($itemResult) | $($item.reason) | $($aggregates) |`n"
    }

    $testResultMarkdown = $testResultMarkdown -replace "%TestResult%", $result

    Add-MtTestResultDetail -Result $testResultMarkdown

    return $testResult
}

﻿function Test-MtCisaDmarcReport {
    <#
    .SYNOPSIS
    Checks state of DMARC records for all exo domains

    .DESCRIPTION
    An agency point of contact SHOULD be included for aggregate and failure reports.

    .EXAMPLE
    Test-MtCisaDmarcReport

    Returns true if DMARC record includes report targets within same domain

    .PARAMETER Strict
    Require the CISA explicit 2nd level validation

    .LINK
    https://maester.dev/docs/commands/Test-MtCisaDmarcReport
    #>
    [CmdletBinding()]
    [OutputType([bool])]
    param(
        # Check 2nd Level Domains Explicitly per CISA
        [switch]$Strict
    )

    $acceptedDomains = Get-MtExo -Request AcceptedDomain
    <# Parked domains should have DMARC with reject policy
    $sendingDomains = $acceptedDomains | Where-Object {`
        -not $_.SendingFromDomainDisabled
    }
    #>
    $expandedDomains = @()
    foreach($domain in $acceptedDomains){
        #This regex does NOT capture for third level domain scenarios
        #e.g., example.co.uk; example.ny.us;
        $matchDomain = "(?:^|\.)(?'second'[\w-]+\.[\w-]+$)"
        $dmarcMatch = $domain.domainname -match $matchDomain
        if($dmarcMatch){
            $expandedDomains += $Matches.second
            if($domain.domainname -ne $Matches.second){
                $expandedDomains += $domain.domainname
            }
        }else{
            $expandedDomains += $domain.domainname
        }
    }

    $dmarcRecords = @()
    foreach($expandedDomain in $expandedDomains){
        $dmarcRecord = Get-MailAuthenticationRecord -DomainName $expandedDomain -Records DMARC
        $dmarcRecord | Add-Member -MemberType NoteProperty -Name "pass" -Value "Failed"
        $dmarcRecord | Add-Member -MemberType NoteProperty -Name "reason" -Value ""

        $checkType = $dmarcRecord.dmarcRecord.GetType().Name -eq "DMARCRecord"
        $hostsAggregate = $dmarcRecord.dmarcRecord.reportAggregate.mailAddress.Host
        $hostsForensic = $dmarcRecord.dmarcRecord.reportForensic.mailAddress.Host

        if($checkType -and $expandedDomain -in $hostsAggregate -and $expandedDomain -in $hostsForensic){
            $dmarcRecord.pass = "Passed"
        }elseif($checkType){
            $dmarcRecord.reason = "No target in domain"
        }elseif($dmarcRecord.dmarcRecord -like "*not available"){
            $dmarcRecord.pass = "Skipped"
            $dmarcRecord.reason = $dmarcRecord.dmarcRecord
        }else{
            $dmarcRecord.reason = $dmarcRecord.dmarcRecord
        }

        $dmarcRecords += $dmarcRecord
    }

    if("Failed" -in $dmarcRecords.pass -and $Strict){
        $testResult = $false
    }elseif("Failed" -in $dmarcRecords.pass -and -not $Strict){
        if("Failed" -in ($dmarcRecords|Where-Object{$_.domain -in $acceptedDomains.DomainName}).pass){
            $testResult = $false
        }else{
            $testResult = $true
        }
    }elseif("Failed" -notin $dmarcRecords.pass -and "Passed" -notin $dmarcRecords.pass){
        Add-MtTestResultDetail -SkippedBecause NotSupported
        return $null
    }else{
        $testResult = $true
    }

    if($testResult){
        $testResultMarkdown = "Well done. Your tenant's domains have in domain report targets. Review report targets.`n`n%TestResult%"
    }else{
        $testResultMarkdown = "Your tenant's second level domains do not have in domain report targets.`n`n%TestResult%"
    }

    $passResult = "✅ Pass"
    $failResult = "❌ Fail"
    $result = "| Domain | Result | Reason | Targets |`n"
    $result += "| --- | --- | --- | --- |`n"
    foreach ($item in $dmarcRecords | Sort-Object -Property domain) {
        switch($item.pass){
            "Passed" {$itemResult = $passResult}
            "Failed" {$itemResult = $failResult}
        }
        $aggregates = $item.dmarcRecord.reportForensic.mailAddress
        $aggregatesCount = ($aggregates|Measure-Object).Count
        if($aggregatesCount -ge 3){
            $aggregates = "$($aggregates[0]), $($aggregates[1]), "
            $aggregates += "& ...$aggregatesCount targets"
        }elseif($aggregatesCount -gt 1){
            $aggregates = $aggregates -join "<br />"
        }
        $forensics = $item.dmarcRecord.reportForensic.mailAddress
        $forensicsCount = ($forensics|Measure-Object).Count
        if($forensicsCount -ge 3){
            $forensics = "$($forensics[0]), $($forensics[1]), "
            $forensics += "& ...$forensicsCount targets"
        }elseif($aggregatesCount -gt 1){
            $forensics = $forensics -join ", "
        }

        $result += "| $($item.domain) | $($itemResult) | $($item.reason) | Aggregate Reports: $($aggregates) |`n"
        $result += "| $($item.domain) | $($itemResult) | $($item.reason) | Forensic Reports: $($forensics) |`n"
    }

    $testResultMarkdown = $testResultMarkdown -replace "%TestResult%", $result

    Add-MtTestResultDetail -Result $testResultMarkdown

    return $testResult
}

